-- Refuse rollback while capabilities using the motion actions remain retained.
ALTER TABLE farm.pause_authority_challenges DROP CONSTRAINT control_capability_actions;
ALTER TABLE farm.pause_authority_challenges ADD CONSTRAINT control_capability_actions CHECK (capability IS NULL OR (capability ? 'actions' AND jsonb_typeof(capability->'actions') = 'array' AND jsonb_array_length(capability->'actions') BETWEEN 1 AND 15 AND capability->'actions' <@ '["pause","resume","cancel","emergency_stop","set_temperature","set_fan","home","set_light","set_speed","start_print","firmware_restart","run_macro","load_filament","unload_filament","extrude"]'::jsonb AND (NOT (capability->'actions' ? 'run_macro') OR COALESCE(capability->>'role' IN ('owner','admin'), false))));
